mapper.select:
SELECT id, compensation_id, biz_type, biz_id, failure_type, status,
       retry_count, max_retry_count, next_retry_at, payload, last_error,
       created_at, updated_at, completed_at
FROM compensation_record
WHERE biz_type = #{bizType}
  AND biz_id = #{bizId}
  AND failure_type = #{failureType}
  AND status IN ('PENDING', 'RUNNING', 'FAILED')
ORDER BY id DESC
LIMIT 1

